/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import BackwardAccelerationColors from "../../src/BackwardAccelerationColors.js";
import { PredictionNotebook } from "../../src/common/model/PredictionNotebook.js";
import { StringManager } from "../../src/i18n/StringManager.js";
import { LabScreen } from "../../src/lab/LabScreen.js";
import { BackwardAccelerationPreferencesModel } from "../../src/preferences/BackwardAccelerationPreferencesModel.js";
import { SmartCartScreen } from "../../src/smart-cart/SmartCartScreen.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();

  // Simulation-specific preferences; initial values come from backwardAccelerationQueryParameters.
  const simPreferences = new BackwardAccelerationPreferencesModel(Tandem.ROOT.createTandem("preferences"));

  // One notebook of predictions and sign tables for both screens: predict once, then
  // compare with the virtual cart and with the real Smart Cart.
  const notebook = new PredictionNotebook();

  const screens = [
    new LabScreen({
      name: stringManager.getScreenNames().labStringProperty,
      tandem: Tandem.ROOT.createTandem("labScreen"),
      notebook,
      smoothing: simPreferences,
      backgroundColorProperty: BackwardAccelerationColors.backgroundColorProperty,
    }),
    new SmartCartScreen({
      name: stringManager.getScreenNames().smartCartStringProperty,
      tandem: Tandem.ROOT.createTandem("smartCartScreen"),
      notebook,
      smoothing: simPreferences,
      backgroundColorProperty: BackwardAccelerationColors.backgroundColorProperty,
    }),
  ];

  return { screens, tracked: { BackwardAccelerationColors, stringManager, simPreferences, notebook } };
}

let sim: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    sim = buildSim();
    return sim.screens;
  },
  tracked: () => sim?.tracked ?? {},
});
